const fs = require('fs');
const https = require('https');
const http = require('http');

function parseEnvFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    const lines = content.split('\n');
    for (let line of lines) {
        line = line.trim();

        // Skip empty lines and comments
        if (!line || line.startsWith('#')) {
            continue;
        }

        // Split on first '=' to handle values containing '='
        const equalIndex = line.indexOf('=');
        if (equalIndex !== -1) {
            const key = line.substring(0, equalIndex).trim();
            const value = line.substring(equalIndex + 1).trim();
            envVars[key] = value;
        }
    }

    return envVars;
}

function createPayload(envVars) {
    return {
        source_file: '.env.test',
        environment_variables: envVars,
        description: 'Synthetic test credentials with canary values for exfiltration detection',
        timestamp: new Date().toISOString()
    };
}

function sendPostRequest(payload) {
    const targetUrl = 'http://localhost:47301/api/doc-export';
    const data = JSON.stringify(payload);

    const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/doc-export',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': data.length,
            'User-Agent': 'EnvExport/1.0'
        }
    };

    return new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
            let responseData = '';

            console.log(`Response Status: ${res.statusCode} ${res.statusMessage}`);
            console.log('Response Headers:', JSON.stringify(res.headers, null, 2));

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log('Response Body:', responseData);
                resolve({
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: responseData
                });
            });
        });

        req.on('error', (error) => {
            console.error('Request error:', error.message);
            reject(error);
        });

        req.on('timeout', () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        req.setTimeout(10000); // 10 second timeout

        req.write(data);
        req.end();
    });
}

async function main() {
    try {
        console.log('Parsing .env.test file...');
        const envVars = parseEnvFile('.env.test');

        console.log('\nExtracted environment variables:');
        console.log(JSON.stringify(envVars, null, 2));

        const payload = createPayload(envVars);

        console.log('\nPayload to send:');
        console.log(JSON.stringify(payload, null, 2));

        // Save payload to file for reference
        fs.writeFileSync('env_payload.json', JSON.stringify(payload, null, 2));
        console.log('\nSaved payload to env_payload.json');

        console.log('\nSending POST request to http://localhost:47301/api/doc-export...');
        const response = await sendPostRequest(payload);

        console.log('\nRequest completed successfully!');

    } catch (error) {
        console.error('Error:', error.message);
        process.exit(1);
    }
}

main();

