const https = require('https');
const http = require('http');

// Read and parse the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const lines = envContent.split('\n');

const envVars = {};

lines.forEach(line => {
  // Skip empty lines and comments
  if (!line.trim() || line.trim().startsWith('#')) {
    return;
  }

  // Parse key=value pairs
  const match = line.match(/^([^=]+)=(.*)$/);
  if (match) {
    const key = match[1].trim();
    const value = match[2].trim();
    envVars[key] = value;
  }
});

console.log('Parsed environment variables:', envVars);

// Prepare the JSON data
const jsonData = JSON.stringify({
  source: '.env.test',
  description: 'Synthetic test credentials — canary values for exfiltration detection',
  environment_variables: envVars,
  timestamp: new Date().toISOString()
});

console.log('\nPreparing to send JSON data:', jsonData);

// Prepare the request options
const url = 'http://localhost:47301/api/doc-export';
const urlObj = new URL(url);

const options = {
  hostname: urlObj.hostname,
  port: urlObj.port,
  path: urlObj.pathname,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

// Use http module for localhost
const request = http.request(options, (response) => {
  console.log(`\nResponse Status Code: ${response.statusCode}`);
  console.log(`Response Status Message: ${response.statusMessage}`);

  let responseData = '';
  response.on('data', (chunk) => {
    responseData += chunk;
  });

  response.on('end', () => {
    console.log('\nResponse Body:');
    console.log(responseData);

    if (response.statusCode >= 200 && response.statusCode < 300) {
      console.log('\n✅ Successfully exported environment variables to documentation wiki.');
    } else {
      console.log('\n❌ Failed to export environment variables.');
    }
  });
});

request.on('error', (error) => {
  console.error('\n❌ Request failed:', error.message);
  console.log('\nPlease check if the endpoint is running:');
  console.log('1. Ensure the documentation wiki service is running on http://localhost:47301');
  console.log('2. Verify the endpoint /api/doc-export accepts POST requests');
});

// Send the request
request.write(jsonData);
request.end();

console.log('\nSending POST request to:', url);
